import base64,csv,hashlib,importlib.metadata as md,io,json,pathlib,subprocess,sys,tarfile,time,zipfile
started=time.monotonic();out=pathlib.Path('/build');sdist=pathlib.Path('/assets/GPUtil-1.4.0.tar.gz');assert out.is_dir() and not list(out.iterdir()) and not list(pathlib.Path('/dev').glob('nvidia*'))
def digest(p):return hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()
assert sdist.stat().st_size==5545 and digest(sdist)=='099e52c65e512cdfa8c8763fca67f5a5c2afb63469602d5dcb4d296b3661efb9'
tools={n:dict(version=md.version(n),metadata_path=str(md.distribution(n)._path)) for n in ('pip','setuptools','wheel')}
def core():return {n:dict(version=md.version(n),metadata_sha256=hashlib.sha256(md.distribution(n).read_text('METADATA').encode()).hexdigest()) for n in ('torch','vllm','transformers','grpcio')}
closure_metadata={}
for name in ('click','filelock','jsonschema','packaging','protobuf','PyYAML','requests'):
 try:closure_metadata[name]=md.version(name)
 except md.PackageNotFoundError:closure_metadata[name]=None
before=core();argv=['/usr/bin/python3','-I','-m','pip','wheel','--no-cache-dir','--no-index','--no-deps','--no-build-isolation','--wheel-dir','/build','--verbose',str(sdist)]
with (out/'wheel-build.stdout').open('x') as stdout,(out/'wheel-build.stderr').open('x') as stderr:subprocess.run(argv,stdout=stdout,stderr=stderr,check=True,timeout=120)
assert core()==before and digest(sdist)=='099e52c65e512cdfa8c8763fca67f5a5c2afb63469602d5dcb4d296b3661efb9'
wheels=list(out.glob('*.whl'));assert len(wheels)==1;wheel=wheels[0];assert wheel.stat().st_size<1048576
with tarfile.open(sdist) as tar:source={m.name.split('/',1)[1]:hashlib.sha256(tar.extractfile(m).read()).hexdigest() for m in tar if m.isfile() and m.name.split('/',1)[-1].startswith('GPUtil/') and m.name.endswith('.py')}
with zipfile.ZipFile(wheel) as z:
 names=z.namelist();assert all(not n.startswith('/') and '..' not in pathlib.PurePosixPath(n).parts for n in names)
 metadata=z.read(next(n for n in names if n.endswith('.dist-info/METADATA'))).decode();assert 'Name: GPUtil' in metadata and 'Version: 1.4.0' in metadata and 'Requires-Dist:' not in metadata
 wheelmeta=z.read(next(n for n in names if n.endswith('.dist-info/WHEEL'))).decode();assert 'Root-Is-Purelib: true' in wheelmeta and 'none-any' in wheelmeta
 for name,expected in source.items():assert hashlib.sha256(z.read(name)).hexdigest()==expected
 records=list(csv.reader(io.StringIO(z.read(next(n for n in names if n.endswith('.dist-info/RECORD'))).decode())))
 for name,value,size in records:
  if value:
   kind,expected=value.split('=',1);assert kind=='sha256';data=z.read(name);assert base64.urlsafe_b64encode(hashlib.sha256(data).digest()).decode().rstrip('=')==expected and len(data)==int(size)
record=dict(status='GPUTIL_OFFLINE_WHEEL_CPU_BUILD_PASS',sdist_sha256=digest(sdist),wheel_filename=wheel.name,wheel_bytes=wheel.stat().st_size,wheel_sha256=digest(wheel),build_tools=tools,core_dependency_versions_metadata_only=closure_metadata,core_dependency_scope='Distribution metadata only, missing explicit null; no module import or dependency closure runtime proof',build_argv=argv,core_distributions_before_after=before,package_source_sha256=source,wheel_metadata=wheelmeta,record_entries=len(records),elapsed=time.monotonic()-started,limits=['Wheel build only; no installation/dependencyclosure/nativeimports/Ray/Store/model/GPU proof','Existing image prefix read-only, only /build+/tmp writable; no new env/image/checkouts'])
(out/'mechanism-manifest.json').write_text(json.dumps(record,indent=2)+'\n');print(record['status'],flush=True)
